#[test]
fn test_answers_in_any_order_are_appended_in_id_order() {
    let p: &mut crate::emon::planctx::Plan = &mut crate::emon::planctx::Plan::new();
    t_init(p, 5, 24);
    pl_attempt(p);
    t_render(p, 9);
    t_render(p, 2);
    t_render(p, 6);
    pl_after(p, us_requests());
    crate::testport::assert_eq(pl_owed(p), 3, "three owed");
    crate::testport::assert_eq(t_answer(p, 6), 0, "6 first");
    crate::testport::assert_eq(pl_has(p, 6), 1, "6 is in");
    crate::testport::assert_eq(pl_has(p, 2), 0, "2 is not");
    crate::testport::assert_eq(pl_owed(p), 2, "two owed");
    crate::testport::assert_eq(t_answer(p, 9), 0, "then 9");
    crate::testport::assert_eq(t_answer(p, 2), 0, "then 2");
    crate::testport::assert_eq(pl_owed(p), 0, "none owed");
    crate::testport::assert_eq(pl_commit(p), 0, "committed");
    crate::testport::assert_eq(rec_count(&mut p.ans), 3, "three answers");
    crate::testport::assert_eq(crate::port::cells_at(&mut p.ans, 2), 2, "id 2 first");
    crate::testport::assert_eq(t_nth_id(&mut p.ans, 1), 6, "then 6");
    crate::testport::assert_eq(t_nth_id(&mut p.ans, 2), 9, "then 9");
    crate::testport::assert_eq(crate::port::cells_len(&mut p.reqs), 0, "the round is over");
}
#[test]
fn test_the_transcript_has_an_entry_per_answer_in_id_order() {
    let p: &mut crate::emon::planctx::Plan = &mut crate::emon::planctx::Plan::new();
    t_init(p, 5, 24);
    pl_attempt(p);
    t_render(p, 5);
    t_ocr(p, 1);
    pl_after(p, us_requests());
    t_answer(p, 5);
    crate::port::cells_drop(&mut p.cur, 0);
    an_fail(&mut p.cur, pk_ocr(), 1, ps_unsupported());
    pl_offer(p);
    pl_commit(p);
    crate::testport::assert_eq(tx_round(&mut p.tx, 0), 0, "round 0");
    crate::testport::assert_eq(t_tx_req_id(&mut p.tx, 0), 1, "the OCR of id 1 first");
    crate::testport::assert_eq(t_tx_ans_id(&mut p.tx, 0), 1, "and its answer");
    crate::testport::assert_eq(t_tx_ans_status(&mut p.tx, 0), ps_unsupported(), "unsupported");
    let nxt: i32 = tx_next(&mut p.tx, 0);
    crate::testport::assert_eq(tx_round(&mut p.tx, nxt), 0, "round 0 again");
    crate::testport::assert_eq(t_tx_req_id(&mut p.tx, nxt), 5, "then the render of 5");
    crate::testport::assert_eq(t_tx_ans_status(&mut p.tx, nxt), ps_ok(), "ok");
    crate::testport::assert_eq(tx_next(&mut p.tx, nxt), crate::port::cells_len(&mut p.tx), "and that is all");
}
