#[test]
fn test_a_finished_unit_is_folded_into_the_totals() {
    let p: &mut crate::emon::planctx::Plan = &mut crate::emon::planctx::Plan::new();
    t_init(p, 5, 24);
    pl_attempt(p);
    pl_after(p, us_need_bytes());
    pl_attempt(p);
    t_render(p, 1);
    t_render(p, 2);
    pl_after(p, us_requests());
    p.bytes_requests = 4;
    pl_fold(p);
    crate::testport::assert_eq(p.t_attempts, 2, "attempts");
    crate::testport::assert_eq(p.t_fetch_rounds, 1, "fetch rounds");
    crate::testport::assert_eq(p.t_bytes_requests, 4, "bytes requests");
    crate::testport::assert_eq(p.t_requests, 2, "requests");
    crate::testport::assert_eq(p.attempts, 0, "the unit is reset");
    crate::testport::assert_eq(crate::port::cells_len(&mut p.ans), 0, "its answers are gone");
    en_next(p, 1, 1, 0, 2);
    pl_attempt(p);
    t_render(p, 3);
    pl_after(p, us_requests());
    pl_fold(p);
    crate::testport::assert_eq(p.t_attempts, 3, "the asset unit counts its attempts too");
    crate::testport::assert_eq(p.t_requests, 3, "and its requests");
    en_next(p, 1, 1, 0, 2);
    pl_attempt(p);
    t_render(p, 4);
    t_render(p, 5);
    pl_after(p, us_requests());
    pl_fold(p);
    crate::testport::assert_eq(p.t_attempts, 3, "a page unit does not count its attempts");
    crate::testport::assert_eq(p.t_requests, 5, "but its requests");
    crate::testport::assert_eq(crate::port::cells_len(&mut p.pgq), 1, "it keeps the requests it made");
    crate::testport::assert_eq(crate::port::cells_at(&mut p.pgq, 0), 2, "two");
    crate::testport::assert_eq(crate::port::cells_at(&mut p.pgr, 0), 1, "in one round");
}
#[test]
fn test_the_ports_a_request_goes_to() {
    crate::testport::assert_eq(pl_route(pk_decode(), 0), rt_decode(), "decode: the host's codecs");
    crate::testport::assert_eq(pl_route(pk_decode_img(), 0), rt_decode_img(), "decode-img: the host's codecs");
    crate::testport::assert_eq(pl_route(pk_ocr(), 0), rt_unsupported(), "ocr with no engine");
    crate::testport::assert_eq(pl_route(pk_ocr(), pp_ocr()), rt_ocr(), "ocr with one");
    crate::testport::assert_eq(pl_route(pk_ocr(), pp_render()), rt_unsupported(), "a renderer is not an engine");
    crate::testport::assert_eq(pl_route(pk_render(), 0), rt_unsupported(), "render with no renderer");
    crate::testport::assert_eq(pl_route(pk_crop(), 0), rt_unsupported(), "crop with no renderer");
    crate::testport::assert_eq(pl_route(pk_render(), pp_render()), rt_render(), "render with one");
    crate::testport::assert_eq(pl_route(pk_crop(), pp_render() + pp_ocr()), rt_render(), "crop with both");
    crate::testport::assert_eq(pl_route(pk_bytes(), 3), rt_none(), "bytes is the loop's own");
    crate::testport::assert_eq(pl_route(77, 3), rt_none(), "no such kind");
}
