#[test]
fn test_the_spans_of_an_input_a_request_names() {
    let c: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let o: &mut crate::port::Cells = &mut crate::port::Cells::new();
    rq_decode(c, 1, 0, 100, 50, 0, 0);
    rq_decode(c, 2, 3, 100, 50, 0, 0);
    rq_decode(c, 3, 0, -1, 50, 0, 0);
    rq_decode(c, 4, 0, 100, 0, 0, 0);
    rq_render(c, 5, 0, 0, 144, 0);
    crate::testport::assert_eq(pl_spans(c, 0, 0, o), 1, "a decode of this input");
    crate::testport::assert_eq(crate::port::cells_at(o, 0), 100, "its offset");
    crate::testport::assert_eq(crate::port::cells_at(o, 1), 50, "its length");
    crate::testport::assert_eq(pl_spans(c, 8, 0, o), 0, "a decode of another input");
    crate::testport::assert_eq(pl_spans(c, 16, 0, o), 0, "a decode at a negative offset");
    crate::testport::assert_eq(pl_spans(c, 24, 0, o), 0, "a decode of no bytes");
    crate::testport::assert_eq(pl_spans(c, 32, 0, o), 0, "a render names no bytes");
    crate::testport::assert_eq(crate::port::cells_len(o), 2, "nothing else was written");
}
pub(crate) fn t_zeros(c: &mut crate::port::Cells, n: i32) -> i32 {
    // Append n zeros: the words of two SHA-256s, or a residency map with nothing resident.
    let mut i: i32 = 0;
    while i < n {
        crate::port::cells_push(c, 0);
        i += 1;
    }
    return 0;
}
