pub(crate) fn t_plan_fetch(pend: &mut crate::port::Cells, hint: &mut crate::port::Cells, res: &mut crate::port::Cells, chunk: i32, total: i32, round: i32, out: &mut crate::port::Cells) -> i32 {
    return fp_plan(pend, hint, res, chunk, total, 7, round, out);
}
pub(crate) fn t_range(emon_t: i32, out: &mut crate::port::Cells, k: i32, off: i32, ln: i32, msg: &str) -> i32 {
    // Range k of the plan is `off` and `ln` long, of input 7.
    crate::testport::assert_eq(crate::port::cells_at(out, k * 3), 7, msg);
    crate::testport::assert_eq(crate::port::cells_at(out, (k * 3) + 1), off, msg);
    crate::testport::assert_eq(crate::port::cells_at(out, (k * 3) + 2), ln, msg);
    return 0;
}
